      if (times.length >= ADD_LIMIT) return fail('TooMany', {})
      times.push(now)
      const item = { id: notes.nextId(), title: clean, body: '', pinned: false, createdAt: new Date().toISOString(), archived: false, sharedWith: [], number: nextNumber(notes, keyOf(session)) }
      items.unshift(item)
      forget(session)
      return view(item)
    }),
    implement(removeNote, ({ id }, { fail, session }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const at = items.findIndex((item) => item.id === id)
      if (at < 0) return fail('NotFound', { id })
      if (items[at]?.archived) return fail('Archived', { id })
      const [item] = items.splice(at, 1)
      if (session && item) undo.set(undoKeyOf(session), { items: [{ item, at }] })
      return { id }
    }),
    implement(removeNotes, ({ ids }, { session, fail }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const items = ownListOf(session)
      const removed: { item: Item; at: number }[] = []
      items.forEach((item, at) => {
        if (ids.includes(item.id) && !item.archived) removed.push({ item, at })
      })
      for (const { item } of removed) items.splice(items.findIndex((entry) => entry.id === item.id), 1)
      if (session && removed.length > 0) undo.set(undoKeyOf(session), { items: removed })
      else forget(session)
      return { ids: removed.map(({ item }) => item.id) }
    }),
    implement(archiveNotes, ({ ids }, { session, fail }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const archived = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of archived) item.archived = true
      forget(session)
      return { ids: archived.map((item) => item.id) }
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const entry = undo.get(undoKeyOf(session))
      return entry ? { title: entry.items[0].item.title, count: entry.items.length } : null
    }),
    implement(undoDelete, (_, { fail, session }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const entry = session ? undo.get(undoKeyOf(session)) : undefined
      if (!session || !entry) return fail('NothingToUndo', {})
      const items = ownListOf(session)
      for (const { item, at } of entry.items) items.splice(Math.min(at, items.length), 0, item)
      forget(session)
      return { ids: entry.items.map(({ item }) => item.id) }
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      forget(session)
      return view(item)
    }),
    implement(saveNote, ({ id, title, body }, { fail, session }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      item.body = body.trim()
      forget(session)
      return view(item)
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      if (session && isReadOnly(users, session)) return fail('ReadOnly', {})
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      forget(session)
      return view(item)
    }),
  ]
}
